/* Types */
/**  The Target "Add to targets" writes into the library and My targets. */
export type AddTarget = 
/**  A saved library Target. */
{ source: "saved"; id: string } | 
/**  A bundled catalogue object. */
{ source: "seed"; id: string } | 
/**  A SIMBAD result, resolved again from its query. */
{ source: "simbad"; query: string };

/**  The session's rig that Add to Project adds because the Project lacks it. */
export type AddedRig = {
	id: string,
	name: string,
};

/**
 *  The session state an admission was decided on. A membership write
 *  records it, and a stale one is refused as a conflict.
 */
export type AdmissionBasis = {
	groupingRevision: number,
	calibrationGeneration: number,
};

/**  One reason a session can't join a Project, in the order they are named. */
export type AdmissionBlocker = 
/**  A Closing, Closed or Archived Project takes no session. */
{ blocker: "project_locked"; lifecycle: ProjectLifecycle } | { blocker: "superseded" } | { blocker: "not_ready"; readiness: SessionReadiness } | 
/**  A group holds sessions of its own rig only. */
{ blocker: "rig_mismatch"; sessionRig: string | null; groupRig: string } | 
/**  The kinds neither pinned nor No. */
{ blocker: "calibration_unsettled"; kinds: InputKind[] } | 
/**
 *  Provisional (lead default 2026-10-16, decision record §9; to confirm
 *  with the owner): pinned kinds whose files changed or went missing.
 *  The session waits in Needs calibration until they are reassigned or
 *  their bytes return; Projects that already hold it keep it.
 */
{ blocker: "calibration_drifted"; kinds: InputKind[] };

/**
 *  A master adopted into a Calibration location. Library corrections of the
 *  source are not carried (R16).
 */
export type AdoptedMaster = AdoptedMaster_Serialize | AdoptedMaster_Deserialize;

/**
 *  A master adopted into a Calibration location. Library corrections of the
 *  source are not carried (R16).
 */
export type AdoptedMaster_Deserialize = {
	id: string,
	revision: number,
	kind: InputKind,
	locationId: string,
	relativePath: NativePathWire,
	fingerprint: ObservationFingerprint_Deserialize,
	classification: Classification,
	observed: CaptureMetadata,
	provenance: MasterProvenance_Deserialize,
	/**  The indexed destination asset, once a scan indexed the copy. */
	assetId?: string | null,
};

/**
 *  A master adopted into a Calibration location. Library corrections of the
 *  source are not carried (R16).
 */
export type AdoptedMaster_Serialize = {
	id: string,
	revision: number,
	kind: InputKind,
	locationId: string,
	relativePath: NativePathWire,
	fingerprint: ObservationFingerprint_Serialize,
	classification: Classification,
	observed: CaptureMetadata,
	provenance: MasterProvenance_Serialize,
	/**  The indexed destination asset, once a scan indexed the copy. */
	assetId: string | null,
};

