/**  What became of a file `PlateVault` didn't place, listed in the Apply sheet. */
export type ForeignItemState = "pending" | 
/**  Ticked and moved into the new View after the swap. */
"moved" | 
/**  Left in `View (previous)/`. */
"stayed" | "failed";

/**
 *  A file in the View that `PlateVault` didn't place (VSEL-FR-20), with the
 *  user's consent. Only a ticked file moves, and only after the swap.
 */
export type ForeignItem_Deserialize = {
	seq: number,
	/**  Relative to `View/`. */
	path: NativePathWire,
	evidence: EntryEvidence_Deserialize,
	ticked: boolean,
	state: ForeignItemState,
	reason: string | null,
};

/**
 *  A file in the View that `PlateVault` didn't place (VSEL-FR-20), with the
 *  user's consent. Only a ticked file moves, and only after the swap.
 */
export type ForeignItem_Serialize = {
	seq: number,
	/**  Relative to `View/`. */
	path: NativePathWire,
	evidence: EntryEvidence_Serialize,
	ticked: boolean,
	state: ForeignItemState,
	reason: string | null,
};

/**  The basis summary shown with a frame state. */
