export type PinState = PinState_Serialize | PinState_Deserialize;

/**  One kind's calibration state on a session. */
export type PinState_Deserialize = 
/**  Not found, or waiting for calibration to arrive. */
({ state: "unresolved" }) & { origin?: never; target?: never } | 
/**
 *  Outside the window, warned or unknown: shown with its evidence until
 *  the user confirms it. Never settled.
 */
({ state: "suggested"; target: PinTarget_Deserialize }) & { origin?: never } | { state: "pinned"; target: PinTarget_Deserialize; origin: PinOrigin } | 
/**  No darks, No flats or No bias. */
({ state: "declined"; origin: DeclineOrigin }) & { target?: never };

/**  One kind's calibration state on a session. */
export type PinState_Serialize = 
/**  Not found, or waiting for calibration to arrive. */
({ state: "unresolved" }) & { origin?: never; target?: never } | 
/**
 *  Outside the window, warned or unknown: shown with its evidence until
 *  the user confirms it. Never settled.
 */
({ state: "suggested"; target: PinTarget_Serialize }) & { origin?: never } | { state: "pinned"; target: PinTarget_Serialize; origin: PinOrigin } | 
/**  No darks, No flats or No bias. */
({ state: "declined"; origin: DeclineOrigin }) & { target?: never };

