/**
 *  One leftover of an Apply with its recorded review. The path is relative to
 *  the Project folder (`<Project>/`): today the file sits in
 *  `View (previous)/`, and where kept files go when the next outgoing View
 *  arrives is still open with the owner (decision record §9).
 */
export type PreviousItem = PreviousItem_Serialize | PreviousItem_Deserialize;

/**  Why a file stayed in `View (previous)/` after the swap (STO-FR-10). */
export type PreviousItemReason = 
/**  A copy that differs from what `PlateVault` placed. */
"changed_copy" | 
/**  A copy whose original couldn't be verified against its digest. */
"unverified_copy" | 
/**  A file `PlateVault` didn't place that the user left unticked. */
"unticked_file" | 
/**  A link that failed the no-follow check. */
"unverified_link";

/**
 *  The user's review of one file `View (previous)/` still holds (D-W110):
 *  keep it where it is, move it into `View/` at the same place, or move it to
 *  the OS Trash. The model's `Pending` is the state the catalog records a
 *  leftover in, and no client sets it.
 */
export type PreviousItemResolution = "kept" | "moved" | "trashed";

/**
 *  The user's review of a leftover (D-W110). A kept file is not asked about
 *  again (decision record §9): the decision is recorded, and the file may
 *  still be moved or trashed later, such as by Wrap up's Clean up.
 */
export type PreviousItemReview = "pending" | "kept" | "moved" | "trashed";

/**
 *  One leftover of an Apply with its recorded review. The path is relative to
 *  the Project folder (`<Project>/`): today the file sits in
 *  `View (previous)/`, and where kept files go when the next outgoing View
 *  arrives is still open with the owner (decision record §9).
 */
export type PreviousItem_Deserialize = {
	path: NativePathWire,
	reason: PreviousItemReason,
	evidence: EntryEvidence_Deserialize,
	review: PreviousItemReview,
};

/**
 *  One leftover of an Apply with its recorded review. The path is relative to
 *  the Project folder (`<Project>/`): today the file sits in
 *  `View (previous)/`, and where kept files go when the next outgoing View
 *  arrives is still open with the owner (decision record §9).
 */
export type PreviousItem_Serialize = {
	path: NativePathWire,
	reason: PreviousItemReason,
	evidence: EntryEvidence_Serialize,
	review: PreviousItemReview,
};

