{ criterion: "max_fwhm_median"; maxArcsec: number | null };

/**
 *  The review label of a frame's library quality (PIX-FR-14), in sort
 *  order. Quality is global (D-W42): a Project leaves frames out through
 *  its own frame choices, never through a review label.
 */
export type QualityLabel = "unreviewed" | "picked" | "rejected";

/**
 *  A session an open Project suggests and doesn't hold (PRJ-FR-09,
 *  PRJ-FR-19), with what keeps it out for now, such as calibration that
 *  isn't settled ("Choose its flats first").
 */
export type ReadyToAdd = {
	projectId: string,
	suggestion: ProjectSuggestion,
	actions: SessionAction[],
};

export type ReasonCode = 
/**  The volume has no OS Trash, or its OS removal deletes immediately. */
"trash_unsupported" | 
/**  The OS refused the move to its Trash; the entry is still in place. */
"trash_failed" | 
/**  The source's identity, size, modification time or SHA-256 differs from its review. */
"source_drift" | 
/**  The source is missing or cannot be read. */
"source_unavailable" | 
/**  A retained original or kept copy is missing or no longer holds its reviewed bytes. */
"kept_copy_unproven" | 
/**  The destination name holds an entry this operation did not write. */
"destination_occupied" | 
/**  The re-read destination differs from the source snapshot. */
"destination_mismatch" | 
/**  The destination folder or this operation's written copy changed. */
"destination_changed" | 
/**  The destination could not be written, synced or installed without replacing anything. */
"write_failed" | 
/**  After an interruption the recorded evidence cannot prove what happened. */
"interrupted" | 
/**
 *  A library frame, an original source, a file in `Output/` or a master
 *  `Processing/` offered: Clean up, Trash and Close never touch it.
 */
"protected";

/**  The Filters strip's recommendation label. */
export type Recommendation = "broadband_ok" | "narrowband_only" | "avoid_tonight";

/**  What a blocked subscription offers. */
export type RecoveryAction = 
/**  Open the platform notification settings. */
"settings" | 
/**  Repeat activation with the shown values. */
"retry";

/**  Kind of a record outside the library that holds library asset ids. */
export type ReferenceKind = 
/**  A Project holding copies of the captures it holds (PRJ). */
"project" | 
/**
 *  An adopted master's provenance record, or a session's calibration pins
 *  (CAL).
 */
"calibration";

