/**  Move each entry to the OS Trash. */
"trash" | 
/**  Verified transfer; every source stays where it is. */
"copy" | 
/**
 *  Verified transfer, then each source goes to the OS Trash once it,
 *  and its destination, re-verify against the snapshot.
 */
"move";

