/**
 *  The wire shape [`serialize`] writes: a finite JSON number or the name
 *  of a non-finite value. Exists only for the IPC type derives.
 */
export type Wire = number | null | NonFinite;

/**  Why Wrap up doesn't open, or one of its steps can't run now. */
export type WrapUpBlocker = 
/**  Closed, Closing or Archived: Wrap up is a read-only record. */
{ blocker: "not_open"; lifecycle: ProjectLifecycle } | 
/**  "Apply or discard N changes first ▸" (provisional, `ClosePolicy`). */
{ blocker: "pending_changes"; count: number } | 
/**  One operation runs per Project at a time. */
{ blocker: "operation_running"; kind: ProjectOperationKind };

/**  Proceeding with nothing selected records a step Skipped. */
export type WrapUpOutcome = "finished" | "skipped";

/**
 *  One recorded Wrap up step; the Wrap up tab of a Closed Project is the
 *  read-only record of these.
 */
export type WrapUpRecord = {
	step: WrapUpStep,
	outcome: WrapUpOutcome,
	/**  The operation that carried the step out, if it moved anything. */
	operationId: string | null,
	recordedAt: string,
};

/**
 *  Where a Project's Wrap up stands: its recorded steps and the step that
 *  is current.
 */
export type WrapUpStatus = {
	projectId: string,
	lifecycle: ProjectLifecycle,
	desiredRevision: number,
	blocker: WrapUpBlocker | null,
	/**  The recorded steps in order; a Closed Project's read-only record. */
	records: WrapUpRecord[],
	/**  The first step not recorded yet, while Wrap up is open. */
	current: WrapUpStep | null,
};

/**  Wrap up's steps, in their fixed order. */
export type WrapUpStep = "clean_up" | "trash" | "archive";

/**  Whether a destination folder can take new files, checked without writing. */
export type Writability = { state: "writable" } | { state: "not_writable"; detail: string } | 
/**
 *  No check that writes nothing could answer: the platform has none, or
 *  the Windows access check failed for a reason other than a refusal. A
 *  failed write still blocks only its item.
 */
{ state: "unknown"; detail: string };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

